function solve(s) {
  function nthWord(idx) {
    let i = 0;
    let count = 0;
    while (i < s.length) {
      while (i < s.length && s[i] === ' ') i++;
      if (i >= s.length) return null;
      const start = i;
      while (i < s.length && s[i] !== ' ') i++;
      if (count === idx) return [start, i];
      count++;
    }
    return null;
  }

  let total = 0;
  while (nthWord(total) !== null) total++;

  let out = '';
  for (let k = total - 1; k >= 0; k--) {
    const w = nthWord(k);
    if (out !== '') out += ' ';
    out += s.slice(w[0], w[1]);
  }
  return out;
}

function solve(s) {
  let i = s.length - 1;
  const words = [];
  while (i >= 0) {
    while (i >= 0 && s[i] === ' ') i--;
    if (i < 0) break;
    const end = i;
    while (i >= 0 && s[i] !== ' ') i--;
    words.push(s.slice(i + 1, end + 1));
  }
  return words.join(' ');
}
